//! This library provides Diagnostics traits that are intended to be used by autogenerated middleware code.
#![allow(missing_docs, dead_code)]
use diagnostics_api::event::Status;

pub struct Event<T> {
    pub status: Status,
    pub extended_data: Option<T>,
}

impl<T> Event<T> {
    pub fn new(status: Status, extended_data: Option<T>) -> Self {
        Self { status, extended_data }
    }
}
